from sys import stdin, stdout
T = int(stdin.readline())

def presuf(pre, suf):
	for s in bts:
		for i in range(len(s) - 1):
			(pre[s[:i + 1]], suf[s[len(s) - i - 1:]]) = (True, True)
	return (pre, suf)
for _ in range(T):
	a = stdin.readline().strip('\n')
	na = len(a)
	b = stdin.readline().strip('\n')
	nb = len(b)
	A = [0] * (na + 1)
	B = [0] * (nb + 1)
	(n, bts, AB) = (int(stdin.readline()), {}, [[0 for i in range(nb + 1)] for j in range(na + 1)])
	for i in range(n):
		(s, bt) = stdin.readline().split(' ')
		bt = int(bt)
		bts[s] = bt
	(pre, suf) = presuf({}, {})
	As = {}
	done = {}
	for k in range(min(26, na), 0, -1):
		for i in range(na, k - 1, -1):
			s = a[i - k:i]
			if s in bts:
				A[i] += bts[s]
			if s not in pre:
				continue
			if i in done:
				del pre[s]
				continue
			for j in range(k):
				if s[k - j - 1:] not in As:
					As[s[k - j - 1:]] = []
				As[s[k - j - 1:]].append(i)
				done[i] = True
			del pre[s]
	(Bs, done, mx) = ({}, {}, 0)
	for k in range(min(26, nb), 0, -1):
		for i in range(nb - k + 1):
			s = b[i:i + k]
			if s in bts:
				B[i + 1] += bts[s]
			if s not in suf:
				continue
			if i in done:
				del suf[s]
				continue
			for j in range(k):
				if s[:j + 1] not in Bs:
					Bs[s[:j + 1]] = []
				Bs[s[:j + 1]].append(i + 1)
				done[i] = True
			del suf[s]
	for i in range(1, na + 1, 1):
		A[i] = A[i] + A[i - 1]
	for i in range(nb - 1, -1, -1):
		B[i] = B[i] + B[i + 1]
	for s in bts:
		for i in range(1, len(s)):
			st = s[:i]
			en = s[i:]
			bt = bts[s]
			if st in As and en in Bs:
				for x in As[st]:
					for y in Bs[en]:
						AB[x][y] += bt
	for i in range(na + 1):
		for j in range(nb + 1):
			mx = max(A[i] + B[j] + AB[i][j], mx)
	print(mx)
